INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1034501040, 4, 1034501, "わあ……素敵なケーキね！\nえ？　キミが作ったの？\nすごいじゃない！", "", 1, 1, 0, 0, 11, 103411);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1034501041, "", 1034501, "", "", "", "", "", "", 91, 0);
