INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1034501046, 5, 1034501, "なんでって、それは……\nキミがお祝いに来てくれるかも、\nなんて思ってたから……", "", 1, 1, 0, 0, 11, 103411);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1034501047, "", 1034501, "", "", "", "", "", "", 91, 0);
