INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1034501049, 5, 1034501, "だから、今日は麦しゅわは封印よ。\n麦しゅわもありの大人な誕生日は、\nキミが大人になってから……ね？", "", 1, 1, 0, 0, 11, 103411);
