INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1046501043, 6, 1046501, "たい焼きの他にケーキまで\n作れるにゃんて……\nキミって意外と料理上手にゃ？", "", 1, 1, 0, 0, 11, 104611);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1046501044, "", 1046501, "", "", "", "", "", "", 91, 0);
