INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1051501052, 6, 1051501, "君には健康でいてもらって\nまた誕生日を祝ってもらいたいもの。\nまあ、薬が効きすぎて\n変なことになってもご愛敬ね。", "", 1, 1, 0, 0, 11, 105111);
