INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1052501043, 6, 1052501, "おめでとうって言ってもらえるだけでも\nうれしいのに、手作りのケーキまで……\n私、あなたにいろんなものを\nもらってばっかりね。", "", 1, 1, 0, 0, 11, 105211);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1052501044, "", 1052501, "", "", "", "", "", "", 91, 0);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1052501045, 0, 1052501, "vo_adv_1052501_002", "", "", 0, "", "", 21, "vo_adv_1052501");
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1052501046, 5, 1052501, "少しでもお返ししたいけど……\nあなたは何かしてほしいことはある？\nえ？　私の誕生日だから私が\n喜んでくれたらうれしい……？", "", 1, 1, 0, 0, 11, 105211);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1052501047, "", 1052501, "", "", "", "", "", "", 91, 0);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1052501048, 0, 1052501, "vo_adv_1052501_003", "", "", 0, "", "", 21, "vo_adv_1052501");
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1052501049, 5, 1052501, "私、もう十分に喜んでるわ！\nでも、あなたのそんな言葉を聞いたら\nもう少しわがままを\n言いたくなっちゃうわ。", "", 1, 1, 0, 0, 11, 105211);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1052501050, "", 1052501, "", "", "", "", "", "", 91, 0);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1052501051, 0, 1052501, "vo_adv_1052501_004", "", "", 0, "", "", 21, "vo_adv_1052501");
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1052501052, 4, 1052501, "ケーキをあーんしてもらってもいい？\n一口だけ、一口だけでいいから！\nいいの？　ありがとう！\n最高の誕生日だわ！", "", 1, 1, 0, 0, 11, 105211);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1052501053, "", 1052501, "", "", "", "", "", "", 91, 0);
