INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1057501049, 5, 1057501, "ゆっくりでいいからがんばって\n騎空団として成長して……\nいつかは蒼い空を自由に旅したいな。\nもちろん、その時はあなたも一緒だよ！", "", 1, 1, 0, 0, 11, 105711);
