INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501040, 4, 1070501, "ふむ、よい趣向ですね。\n敬うべき相手を忘れず、恩を忘れず、\n健勝を祝う宴を開く……\n礼節を弁えた人間は好きですよ。", "", 1, 1, 0, 0, 11, 107011);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501041, "", 1070501, "", "", "", "", "", "", 91, 0);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501042, 0, 1070501, "vo_adv_1070501_001", "", "", 0, "", "", 21, "vo_adv_1070501");
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501043, 5, 1070501, "しかし一時には\n赤子同然だった貴方が\nここまで成長したこと……\nとても喜ばしく思います。", "", 1, 1, 0, 0, 11, 107011);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501044, "", 1070501, "", "", "", "", "", "", 91, 0);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501045, 0, 1070501, "vo_adv_1070501_002", "", "", 0, "", "", 21, "vo_adv_1070501");
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501046, 5, 1070501, "ただ、そうですね……\n厚意に預かるばかり、\nというのも性に合いませんし。\n何かご褒美をあげましょう。", "", 1, 1, 0, 0, 11, 107011);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501047, "", 1070501, "", "", "", "", "", "", 91, 0);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501048, 0, 1070501, "vo_adv_1070501_003", "", "", 0, "", "", 21, "vo_adv_1070501");
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501049, 5, 1070501, "焦って決めずとも構いません。\n今日は一日、私が飽きるまで\n貴方に付き合ってもらう予定ですから。\nふふ……期待していますよ？", "", 1, 1, 0, 0, 11, 107011);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501050, "", 1070501, "", "", "", "", "", "", 91, 0);
